/* Local UX prototype only. Role switching and validation simulate behavior; they are NOT security controls. */
(() => {
'use strict';
const KEY='kandil-hr-portal-prototype-v1';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7M5 9v11h5v-6h4v6h5V9',file:'M14 2H6a2 2 0 0 0-2 2v16h16V8zM14 2v6h6M8 12h8M8 16h5',check:'m5 12 4 4L19 6',approval:'M9 3H5v18h14V3h-4M9 2h6v4H9zM8 13l3 3 5-6',briefcase:'M3 7h18v13H3zM8 7V4h8v3M3 12a20 20 0 0 0 18 0M10 12h4v3h-4z',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M15 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',calendar:'M4 5h16v16H4zM16 3v4M8 3v4M4 10h16M8 14h2M14 14h2M8 18h2',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',plus:'M12 5v14M5 12h14',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',arrow:'M5 12h14m-5-5 5 5-5 5',close:'m6 6 12 12M18 6 6 18',help:'M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5M12 18h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',globe:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M2 12h20M12 2c5 5 5 15 0 20-5-5-5-15 0-20',logout:'M9 3H4v18h5M10 12h11m-4-4 4 4-4 4',reset:'M3 11a9 9 0 1 1 2 7M3 4v7h7',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6zM8 12l3 3 5-6',menu:'M4 6h16M4 12h16M4 18h16',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',edit:'m16 3 5 5L8 21H3v-5zM13 6l5 5',filter:'M3 4h18l-7 8v7l-4 2V12z',trend:'m3 17 6-6 4 4 8-11M15 4h6v6',note:'M4 3h16v18H4zM8 8h8M8 12h8M8 16h5'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
const initial=()=>({version:1,lang:'ar',role:null,requests:[
 {id:'HR-2026-041',job:'cost',department:'finance',owner:'manager',status:'pending',priority:'urgent',lines:[{branch:'obour',qty:2}],reason:'دعم فريق التكاليف مع زيادة حجم التشغيل ومتابعة مراكز التكلفة.',reasonEn:'Expand cost control coverage as production activity grows.',start:'2026-11-01',type:'full',revision:1,seed:true,history:[{action:'submitted',actor:'manager',date:'2026-10-11T09:30:00'}]},
 {id:'HR-2026-042',job:'quality',department:'production',owner:'other',status:'pending',priority:'normal',lines:[{branch:'obour',qty:1},{branch:'shoubra',qty:1}],reason:'تغطية ورديات الجودة وإتاحة متابعة منتظمة لخطوط الإنتاج.',reasonEn:'Cover quality shifts and improve production-line checks.',start:'2026-11-05',type:'full',revision:1,seed:true,history:[{action:'submitted',actor:'other',date:'2026-10-11T12:20:00'}]},
 {id:'HR-2026-039',job:'warehouse',department:'logistics',owner:'manager',status:'approved',priority:'normal',lines:[{branch:'obour',qty:3}],reason:'استكمال فريق المخازن في موقع العبور.',reasonEn:'Complete the warehouse team at Obour.',start:'2026-10-25',type:'full',revision:1,seed:true,history:[{action:'submitted',actor:'manager',date:'2026-10-09T10:00:00'},{action:'approved',actor:'hr',date:'2026-10-10T11:00:00'}]}
],vacancies:[{id:'VAC-001',request:'HR-2026-039',job:'warehouse',department:'logistics',branch:'obour',qty:3,filled:1,status:'open',priority:'normal',lead:'salma'},
 {id:'VAC-002',request:'HR-2026-036',job:'cost',department:'finance',branch:'shoubra',qty:2,filled:0,status:'open',priority:'urgent',lead:'ahmed'},
 {id:'VAC-003',request:'HR-2026-034',job:'quality',department:'production',branch:'obour',qty:2,filled:1,status:'open',priority:'normal',lead:'salma'}],draft:null,next:44});
let state;try{state=JSON.parse(localStorage.getItem(KEY));if(state?.version!==1||!Array.isArray(state.requests)||!Array.isArray(state.vacancies))state=initial();}catch{state=initial();}
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast(t('التخزين المحلي غير متاح؛ ستستمر التجربة لهذه الجلسة.','Local storage is unavailable; this session will still work.'));}};
let route='dashboard',step=1,filter='all',search='',mobileOpen=false,homeTab='pending',loginRole='manager',modalFocus=null,busy=false;
const t=(ar,en)=>state.lang==='ar'?ar:en;
const labels={dashboard:['الرئيسية','Overview'],requests:['طلبات التوظيف','Hiring requests'],approvals:['الاعتمادات','Approvals'],vacancies:['الشواغر','Vacancies'],new:['طلب توظيف جديد','New hiring request']};
const jobs={cost:['محاسب تكاليف','Cost accountant','finance'],treasury:['أمين خزينة','Treasury officer','finance'],quality:['مراقب جودة','Quality inspector','production'],technician:['فني تشغيل','Production technician','production'],warehouse:['أمين مخزن','Warehouse officer','logistics']};
const departments={finance:['المالية','Finance'],production:['الإنتاج','Production'],logistics:['اللوجستيات','Logistics']};
const branches={obour:['العبور','Obour'],shoubra:['شبرا الخيمة','Shoubra El Kheima'],katameya:['القطامية','Katameya']};
const people={manager:['عمر حسن','Omar Hassan','مدير الإدارة','Department manager','ع ح','OH'],hr:['مريم أحمد','Mariam Ahmed','مديرة الموارد البشرية','HR manager','م أ','MA'],other:['يوسف عادل','Youssef Adel','مدير الإنتاج','Production manager','ي ع','YA']};
const statusNames={pending:['بانتظار الاعتماد','Pending approval'],approved:['معتمد','Approved'],returned:['أُعيد للتعديل','Changes requested'],draft:['مسودة','Draft'],open:['جارٍ التوظيف','Hiring'],paused:['متوقف مؤقتًا','Paused']};
const jobLabel=id=>t(...(jobs[id]||jobs.cost));
const depLabel=id=>t(...(departments[id]||departments.finance));
const branchLabel=id=>t(...(branches[id]||branches.obour));
const person=id=>t(...(people[id]||people.manager));
const roleLabel=id=>t(...(people[id]||people.manager).slice(2,4));
const initials=id=>t(...(people[id]||people.manager).slice(4,6));
const total=r=>r.lines.reduce((n,l)=>n+Number(l.qty),0);
const pending=()=>state.requests.filter(r=>r.status==='pending');
const ownRequests=()=>state.role==='hr'?state.requests:state.requests.filter(r=>r.owner===state.role);
const badge=s=>`<span class="badge ${s}">${t(...(statusNames[s]||[s,s]))}</span>`;
const priority=r=>r.priority==='urgent'?`<span class="badge urgent">${t('عاجل','Urgent')}</span>`:'';
const currentDate=()=>new Intl.DateTimeFormat(state.lang==='ar'?'ar-EG':'en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'Africa/Cairo'}).format(new Date());
const when=v=>new Intl.DateTimeFormat(state.lang==='ar'?'ar-EG':'en-GB',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit',timeZone:'Africa/Cairo'}).format(new Date(v));
const btn=(text,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
const link=(text,action,extra='')=>`<button class="link-btn" data-action="${action}" ${extra}>${text}${icon('arrow','arrow')}</button>`;
function toast(message){const e=$('#toast');e.textContent=message;e.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('show'),3800);}
function go(next){closeModal();route=next;filter='all';search='';mobileOpen=false;if(next==='new'){ensureDraft();step=1;}render();window.scrollTo(0,0);location.hash=next;}
function ensureDraft(){if(!state.draft)state.draft={id:null,job:'cost',department:'finance',lines:[{branch:'obour',qty:1}],priority:'normal',reason:'',start:'',type:'full'};}
function capacity(branch,exclude=state.draft?.id){const base={obour:6,shoubra:4,katameya:3}[branch];return base-state.requests.filter(r=>!r.seed&&r.id!==exclude&&['pending','approved'].includes(r.status)).flatMap(r=>r.lines).filter(l=>l.branch===branch).reduce((n,l)=>n+l.qty,0);}
function empty(title,body){return `<div class="empty">${icon('check')}<strong>${title}</strong><p>${body}</p></div>`;}
function brand(){return `<div class="brand"><span class="logo-mark" lang="ar">ق</span><div><strong>${t('قنديل','Kandil')}</strong><small>${t('بوابة الموارد البشرية','PEOPLE & CULTURE')}</small></div></div>`;}
function login(){return `<main class="login"><section class="login-story">${brand()}<div class="login-story-content"><div class="kicker">${t('الناس أولًا. والخطوة التالية أوضح.','PEOPLE FIRST. A CLEARER WAY FORWARD.')}</div><h1>${t('كل خطوة في رحلة فريقك،<br>في مكان واحد.','Every step of your<br>people journey.<br>In one place.')}</h1><p>${t('من الاحتياج إلى التعيين. تجربة أبسط تجمع فريق الموارد البشرية والمديرين حول العمل المهم.','From a hiring need to a new team member. A simpler way for HR and managers to move work forward.')}</p><div class="story-progress"><span>${t('طلب','Request')}</span><i></i><span>${t('اعتماد','Approval')}</span><i></i><span>${t('شاغر','Vacancy')}</span></div></div><div class="login-story-footer">${t('قنديل مصر · الموارد البشرية','Kandil Egypt · Human Resources')}</div></section><section class="login-panel"><div class="login-top"><button class="language-btn" data-action="language">${icon('globe')}${t('English','العربية')}</button></div><div class="login-form"><div class="eyebrow">${t('أهلًا بك في قنديل','WELCOME TO KANDIL')}</div><h2>${t('مساحة عملك، بشكل أوضح.','Your work, made clearer.')}</h2><p>${t('اختر دورًا لاستكشاف التجربة التفاعلية.','Choose a role to explore the interactive prototype.')}</p>${['manager','hr'].map(p=>`<label class="role-card ${loginRole===p?'selected':''}"><span class="avatar">${initials(p)}</span><span><strong>${person(p)}</strong><small>${roleLabel(p)}</small></span><input type="radio" name="loginRole" value="${p}" ${loginRole===p?'checked':''}></label>`).join('')}${btn(t('دخول التجربة','Enter prototype')+icon('arrow','arrow'),'login','primary','id="enter-prototype"')}<div class="login-note">${icon('shield')} ${t('نموذج تصميم ببيانات تجريبية. لا يتطلب كلمة مرور، ولا يتصل بسجلات الموظفين.','A design prototype with sample data. No password required. No connection to employee records.')}</div></div><div class="login-bottom">${t('العربية والإنجليزية · تجربة سطح المكتب والموبايل','Arabic & English · Desktop & mobile experience')}</div></section></main>`;}
function shell(content){const user=state.role;return `<aside class="sidebar ${mobileOpen?'open':''}">${brand()}<button class="icon-btn sidebar-close" data-action="menu" aria-label="${t('إغلاق القائمة','Close menu')}">${icon('close')}</button><div class="sidebar-label">${t('مساحة العمل','WORKSPACE')}</div><nav class="nav" aria-label="${t('التنقل الرئيسي','Main navigation')}">${Object.keys(labels).filter(k=>k!=='new').map((k,i)=>`<a href="#${k}" data-route="${k}" class="${route===k||(route==='new'&&k==='requests')?'active':''}" ${route===k?'aria-current="page"':''}>${icon(['home','file','approval','briefcase'][i])}<span>${t(...labels[k])}</span>${k==='approvals'&&ownRequests().filter(r=>r.status==='pending').length?`<span class="nav-count">${ownRequests().filter(r=>r.status==='pending').length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="help-card">${icon('help')}<h3>${t('ابدأ بجولة قصيرة','Take a quick tour')}</h3><p>${t('جرّب رحلة طلب التوظيف، من الإنشاء حتى فتح الشاغر.','Explore a hiring request from creation to an open vacancy.')}</p>${link(t('دليل التجربة','Prototype guide'),'guide')}</div><div class="sidebar-footer"><span class="dot"></span>${t('نموذج تفاعلي · إصدار 01','Interactive prototype · v01')}</div></div></aside><div class="workspace"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="${t('فتح القائمة','Open menu')}" aria-expanded="${mobileOpen}">${icon('menu')}</button><div class="breadcrumb"><span>${t('الموارد البشرية','Human Resources')}</span>${icon('chevron','arrow')}<strong>${t(...labels[route]||labels.dashboard)}</strong></div><div class="topbar-tools"><button class="search-trigger" data-action="search">${icon('search')}<span>${t('ابحث عن طلب أو شاغر...','Search requests, vacancies…')}</span><kbd>⌘ K</kbd></button><button class="language-btn" data-action="language">${icon('globe')}${t('EN','عربي')}</button><button class="icon-btn" data-action="notifications" aria-label="${t('الإشعارات','Notifications')}">${icon('bell')}<i class="notification-dot"></i></button><button class="user-button" data-action="profile"><span class="avatar">${initials(user)}</span><span><strong>${person(user)}</strong><small>${roleLabel(user)}</small></span>${icon('down')}</button></div></header><main class="content"><div class="demo-strip"><span><i class="dot"></i>${t('معاينة التصميم · بيانات تجريبية فقط','Design preview · Sample data only')}</span><div class="demo-role"><label for="demo-role">${t('تجربة الدور:','Preview as:')}</label><select id="demo-role" aria-label="${t('تغيير الدور التجريبي','Switch demo role')}">${['manager','hr'].map(p=>`<option value="${p}" ${state.role===p?'selected':''}>${person(p)} · ${roleLabel(p)}</option>`).join('')}</select></div></div>${content}<footer class="page-footer"><span>${t('قنديل · تجربة أفضل لكل خطوة','Kandil · A better experience at every step')}</span><span>${t('بيانات محلية تجريبية — غير متصل بـ Frappe','Local sample data — not connected to Frappe')}</span></footer></main></div>`;}
function newButton(){return btn(icon('plus')+t('طلب توظيف جديد','New hiring request'),'new','primary');}
function dashboard(){const waiting=ownRequests().filter(r=>r.status==='pending');const active=state.vacancies.filter(v=>v.status==='open');return `<section class="page-head"><div><div class="eyebrow">${currentDate()}</div><h1>${t('أهلًا، '+person(state.role).split(' ')[0]+' 👋','Welcome back, '+person(state.role).split(' ')[0]+' 👋')}</h1><p>${state.role==='hr'?t('كل ما يحتاج قرارك اليوم، في مكان واحد.','Everything that needs your decision today, in one place.'):t('تابع احتياج فريقك، واعرف أين وصلت كل خطوة.','Follow your team’s hiring needs and see what happens next.')}</p></div>${newButton()}</section><section class="stats"><div class="stat"><div class="stat-icon">${icon('approval')}</div><div><strong>${state.role==='hr'?pending().length:waiting.length}</strong><small>${t('طلبات بانتظار الاعتماد','Requests awaiting approval')}</small></div><span class="stat-hint">${t('مراجعة مفتوحة','Open for review')}</span></div><div class="stat"><div class="stat-icon">${icon('briefcase')}</div><div><strong>${active.length}</strong><small>${t('شواغر نشطة','Active vacancies')}</small></div><span class="stat-hint">${active.reduce((n,v)=>n+v.qty-v.filled,0)} ${t('فرص متاحة','open seats')}</span></div><div class="stat"><div class="stat-icon">${icon('calendar')}</div><div><strong>02</strong><small>${t('مقابلات اليوم','Interviews today')}</small></div><span class="stat-hint">${t('جدول توضيحي','Sample schedule')}</span></div></section><div class="dashboard-grid"><div class="stack"><section class="card"><div class="card-head"><div><h2>${state.role==='hr'?t('المطلوب منك','Your action list'):t('متابعة طلباتك','Your requests at a glance')}<span class="count-bubble">${waiting.length}</span></h2><p>${t('الخطوة التالية واضحة، والقرار في مكانه.','A clear next step for every request.')}</p></div>${icon('approval')}</div><div class="tabs"><button class="tab ${homeTab==='pending'?'active':''}" data-action="home-tab" data-tab="pending">${t('قيد المراجعة','In review')}</button><button class="tab ${homeTab==='returned'?'active':''}" data-action="home-tab" data-tab="returned">${t('تحتاج تعديلًا','Changes needed')}</button></div>${taskRows(ownRequests().filter(r=>r.status===homeTab).slice(0,4))}<div class="card-foot">${link(t('عرض كل الطلبات','View all requests'),'goto', 'data-page="requests"')}</div></section><section class="card"><div class="card-head"><h2>${t('آخر المستجدات','Latest updates')}</h2><span class="muted small">${t('سجل التجربة','Demo activity')}</span></div>${ownRequests().slice().reverse().slice(0,3).map(r=>`<div class="request-strip"><div><strong>${jobLabel(r.job)}</strong><div class="sub"><span class="ltr">${r.id}</span> · ${t('الإصدار','Revision')} ${r.revision}</div></div>${badge(r.status)}${link(t('عرض','View'),'detail',`data-id="${r.id}"`)}</div>`).join('')}</section></div><aside class="stack side"><section class="card"><div class="card-head"><h2>${t('جدولك اليوم','Your day')}</h2>${icon('calendar')}</div><div class="calendar"><div class="calendar-month"><span>${t('أكتوبر 2026','October 2026')}</span><span class="badge draft">${t('مثال توضيحي','Sample')}</span></div><div class="week">${t('أحد,إثنين,ثلاثاء,أربعاء,خميس','Sun,Mon,Tue,Wed,Thu').split(',').map((d,i)=>`<div class="day ${i===1?'selected':''}"><span>${d}</span><b>${11+i}</b></div>`).join('')}</div><div class="schedule-item"><time class="ltr">10:30 — 11:00</time><strong>${t('مقابلة · محاسب تكاليف','Interview · Cost accountant')}</strong><p>${t('أحمد سامي · مقابلة فنية','Ahmed Samy · Technical interview')}</p></div><div class="schedule-item"><time class="ltr">13:00 — 13:30</time><strong>${t('مقابلة · أمين مخزن','Interview · Warehouse officer')}</strong><p>${t('كريم علي · مقابلة الموارد البشرية','Karim Ali · HR interview')}</p></div></div><div class="card-foot">${t('شاشة المقابلات ضمن المرحلة التالية','Interview workflows are in the next phase')}</div></section><section class="card"><div class="card-head"><h2>${t('نظرة على الشواغر','Vacancy snapshot')}</h2>${link(t('الكل','All'),'goto','data-page="vacancies"')}</div>${active.slice(0,2).map(v=>`<div class="vacancy-mini"><strong>${jobLabel(v.job)}</strong><div class="mini-line"><small>${branchLabel(v.branch)}</small><small>${v.filled} / ${v.qty} ${t('تم تعيينهم','filled')}</small></div><div class="progress"><span style="width:${v.filled/v.qty*100}%"></span></div></div>`).join('')}</section></aside></div>`;}
function taskRows(rows){if(!rows.length)return empty(t('كل شيء واضح الآن','You’re all caught up'),t('لا توجد طلبات في هذه القائمة.','There are no requests in this view.'));return rows.map(r=>`<div class="task-row"><div class="task-icon">${icon('file')}</div><div class="task-body"><div class="task-title">${jobLabel(r.job)}${priority(r)}</div><div class="task-meta"><span class="ltr">${r.id}</span><span>·</span><span>${depLabel(r.department)}</span><span>·</span><span>${total(r)} ${t('موظفين','positions')}</span></div><div class="task-meta">${r.status==='returned'?t('راجع الملاحظة وأرسل إصدارًا جديدًا','Review the note and submit a new revision'):state.role==='hr'?t('بانتظار مراجعتك للعدد والاحتياج','Review the requested quantity and justification'):t('الخطوة الحالية: مراجعة الموارد البشرية','Current step: HR review')}</div></div>${btn(t(state.role==='hr'?'مراجعة الطلب':'عرض الطلب',state.role==='hr'?'Review request':'View request'),'detail','small',`data-id="${r.id}"`)}</div>`).join('');}
function requests(){const rows=ownRequests().filter(r=>(filter==='all'||r.status===filter)&&matches(r,search));return `<div class="page-head"><div><div class="eyebrow">${t('من الاحتياج إلى الاعتماد','FROM NEED TO APPROVAL')}</div><h1>${t('طلبات التوظيف','Hiring requests')}</h1><p>${t('كل طلب، وإصداراته، والخطوة التالية له.','Every request, its revisions and what comes next.')}</p></div>${newButton()}</div>${state.draft?`<div class="note blue" style="margin-bottom:18px;display:flex;justify-content:space-between;gap:12px;align-items:center"><span>${t('لديك مسودة محفوظة لهذا المتصفح.','You have a draft saved in this browser.')}</span>${btn(t('متابعة المسودة','Continue draft'),'new','small')}</div>`:''}<section class="card"><div class="toolbar">${filters(['all','pending','approved','returned'])}${searchField()}</div><div class="table-wrap"><table><thead><tr><th>${t('الطلب / الوظيفة','Request / role')}</th><th>${t('الإدارة','Department')}</th><th>${t('الموقع والعدد','Location & quantity')}</th><th>${t('الحالة','Status')}</th><th>${t('الإصدار','Revision')}</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="title-link" data-action="detail" data-id="${r.id}">${jobLabel(r.job)}</button><small class="ltr">${r.id}</small></td><td>${depLabel(r.department)}</td><td>${r.lines.length>1?t('مواقع متعددة','Multiple locations'):branchLabel(r.lines[0].branch)}<small>${total(r)} ${t('موظفين مطلوبين','positions requested')}</small></td><td>${badge(r.status)}</td><td><span class="ltr">v${r.revision}</span></td><td>${btn(t('عرض','View'),'detail','small',`data-id="${r.id}"`)}</td></tr>`).join('')}</tbody></table></div>${!rows.length?empty(t('لا توجد نتائج','No matching requests'),t('جرّب بحثًا أو تصفية مختلفة.','Try a different search or filter.')):''}</section>`;}
function filters(values){return `<div class="filter-group">${values.map(v=>`<button class="filter-btn ${filter===v?'active':''}" data-action="filter" data-filter="${v}">${v==='all'?t('الكل','All'):t(...statusNames[v])}</button>`).join('')}</div>`;}
function searchField(){return `<div class="search-field">${icon('search')}<input id="list-search" value="${esc(search)}" placeholder="${t('ابحث بالوظيفة أو رقم الطلب','Search role or request ID')}" aria-label="${t('بحث في القائمة','Search list')}"></div>`;}
function matches(r,q){return !q||[jobLabel(r.job),r.id,r.request,depLabel(r.department),...(r.lines||[{branch:r.branch}]).map(l=>branchLabel(l.branch))].join(' ').toLowerCase().includes(q.toLowerCase());}
function approvals(){const rows=(state.role==='hr'?state.requests:ownRequests()).filter(r=>(filter==='all'?r.status==='pending':r.status===filter)&&matches(r,search));return `<div class="page-head"><div><div class="eyebrow">${t('قرار واضح. وسجل محفوظ.','CLEAR DECISIONS. RECORDED CONTEXT.')}</div><h1>${t('الاعتمادات','Approval inbox')}</h1><p>${state.role==='hr'?t('راجع تفاصيل الاحتياج، ثم اعتمد أو أعد الطلب بملاحظة.','Review the hiring need, then approve or request changes.'):t('تابع الطلبات التي تنتظر قرار الموارد البشرية.','Track requests awaiting an HR decision.')}</p></div><span class="badge pending">${ownRequests().filter(r=>r.status==='pending').length} ${t('قيد المراجعة','in review')}</span></div>${state.role!=='hr'?`<div class="note blue" style="margin-bottom:20px">${t('أنت تشاهد دور مدير الإدارة. لتجربة الاعتماد، بدّل إلى مريم أحمد من أعلى الصفحة.','You are viewing the manager role. Switch to Mariam Ahmed above to try approval.')}</div>`:''}<section class="card"><div class="toolbar">${filters(['all','approved','returned'])}${searchField()}</div>${taskRows(rows)}</section>`;}
function vacancies(){const rows=state.vacancies.filter(v=>(filter==='all'||v.status===filter)&&matches(v,search));return `<div class="page-head"><div><div class="eyebrow">${t('الاحتياج المعتمد، جاهز للخطوة التالية','APPROVED NEEDS, READY FOR THE NEXT STEP')}</div><h1>${t('الشواغر','Vacancies')}</h1><p>${t('تابع المواقع، فريق التوظيف، والتقدم في شغل كل وظيفة.','Track locations, recruiting ownership and progress for each role.')}</p></div><span class="badge open">${state.vacancies.filter(v=>v.status==='open').length} ${t('شواغر نشطة','active vacancies')}</span></div><section class="card"><div class="toolbar">${filters(['all','open','paused'])}${searchField()}</div></section><div class="vacancy-grid">${rows.map(v=>`<article class="card vacancy-card"><div class="vacancy-top">${badge(v.status)}${priority(v)}</div><div><h3>${jobLabel(v.job)}</h3><div class="muted small">${depLabel(v.department)}</div></div><div class="vacancy-meta"><span>${icon('pin')}${branchLabel(v.branch)}</span><span>${icon('file')}<bdi>${v.request}</bdi></span></div><div><div class="mini-line"><span class="seat-count"><b>${v.filled}</b> / ${v.qty} ${t('تم تعيينهم','filled')}</span><span class="muted small">${v.qty-v.filled} ${t('متبقي','remaining')}</span></div><div class="progress"><span style="width:${v.filled/v.qty*100}%"></span></div></div><div class="vacancy-bottom"><div class="avatar-stack"><span>${v.lead==='salma'?t('س م','SM'):v.lead==='ahmed'?t('أ س','AS'):'—'}</span>${v.lead?'<span>+1</span>':''}</div>${link(t('تفاصيل الشاغر','View vacancy'),'vacancy',`data-id="${v.id}"`)}</div></article>`).join('')}</div>${!rows.length?empty(t('لا توجد شواغر هنا','No vacancies here yet'),t('اعتمد طلبًا جديدًا أو غيّر التصفية.','Approve a new request or change the filter.')):''}`;}
function wizard(){ensureDraft();const d=state.draft;return `<div class="page-head"><div><div class="eyebrow">${t('طلب تعيين · HR-REC-F02','HIRING REQUEST · HR-REC-F02')}</div><h1>${d.id?t('تعديل طلب التوظيف','Revise hiring request'):t('طلب توظيف جديد','New hiring request')}</h1><p>${t('حدد الاحتياج، وأضف التفاصيل، ثم راجع قبل الإرسال.','Define the need, add context, then review before submitting.')}</p></div>${btn(icon('arrow','arrow')+t('الطلبات','All requests'),'goto','ghost','data-page="requests"')}</div>${state.role!=='manager'?`<div class="note blue">${t('لإنشاء طلب في هذه التجربة، اختر عمر حسن (مدير الإدارة).','Switch to Omar Hassan (department manager) to create a request in this prototype.')}${btn(t('تجربة دور المدير','Switch to manager'),'switch-manager','small')}</div>`:`<div class="wizard-grid"><section class="card"><div class="steps">${[t('الوظيفة والمواقع','Role & locations'),t('تفاصيل الاحتياج','Hiring details'),t('المراجعة والإرسال','Review & submit')].map((s,i)=>`${i?'<span class="step-line"></span>':''}<div class="step ${step===i+1?'active':step>i+1?'done':''}"><b>${step>i+1?'✓':i+1}</b><span>${s}</span></div>`).join('')}</div><form id="request-form" novalidate><div class="form-body">${step===1?stepOne(d):step===2?stepTwo(d):stepThree(d)}<div id="form-error" class="field-error" role="alert"></div></div><div class="form-footer">${btn(t('حفظ كمسودة','Save draft'),'save-draft','ghost','type="button"')}<div class="actions">${step>1?btn(t('السابق','Back'),'previous','','type="button"'):''}${btn(step===3?t('إرسال للاعتماد','Submit for approval'):t('متابعة','Continue'),step===3?'submit-request':'next','primary','type="button" id="wizard-next"')}</div></div></form></section><aside class="stack"><section class="card info-panel"><h3>${t('مسار الطلب','Request journey')}</h3><div class="route-step done"><strong>${t('مدير الإدارة','Department manager')}</strong><small>${t('إنشاء الطلب وتوضيح الاحتياج','Define and submit the need')}</small></div><div class="route-step active"><strong>${t('الموارد البشرية','Human Resources')}</strong><small>${t('مراجعة العدد والتفاصيل','Review quantity and details')}</small></div><div class="route-step"><strong>${t('فتح الشاغر','Create vacancy')}</strong><small>${t('شاغر لكل موقع بعد الاعتماد','One vacancy per approved location')}</small></div></section><div class="note">${icon('shield')}<br>${t('مسار مبسّط لاختبار التصميم. مسارات القطاع والرئيس التنفيذي ومجلس الإدارة ستُربط لاحقًا بقواعد الخادم.','A simplified design journey. Sector, CEO and board routing will later use the server’s authority rules.')}</div></aside></div>`}`;}
const field=(id,label,content,hint='')=>`<div class="field"><label for="${id}">${label}</label>${content}${hint?`<div class="hint">${hint}</div>`:''}</div>`;
function stepOne(d){return `<h2>${t('ما الذي يحتاجه فريقك؟','What does your team need?')}</h2><p class="form-intro">${t('اختر الوظيفة وحدد العدد المطلوب لكل موقع.','Choose a role and the number of people needed at each location.')}</p><div class="form-grid">${field('department',t('الإدارة *','Department *'),`<select id="department" name="department">${Object.keys(departments).map(k=>`<option value="${k}" ${d.department===k?'selected':''}>${depLabel(k)}</option>`).join('')}</select>`)}${field('job',t('الوظيفة *','Role *'),`<select id="job" name="job">${Object.keys(jobs).filter(k=>jobs[k][2]===d.department).map(k=>`<option value="${k}" ${d.job===k?'selected':''}>${jobLabel(k)}</option>`).join('')}</select>`)}</div><div class="locations"><div class="section-label">${icon('pin')}<h3>${t('المواقع والأعداد','Locations & headcount')}</h3></div>${d.lines.map((l,i)=>`<div class="location-row">${field('branch-'+i,t('الموقع','Location'),`<select id="branch-${i}" data-line="${i}" data-field="branch">${Object.keys(branches).map(k=>`<option value="${k}" ${l.branch===k?'selected':''}>${branchLabel(k)}</option>`).join('')}</select>`)}${field('qty-'+i,t('العدد *','Quantity *'),`<input id="qty-${i}" type="number" min="1" max="50" step="1" data-line="${i}" data-field="qty" value="${esc(l.qty)}">`)}<div class="capacity-note">${t('المتاح تجريبيًا','Demo available')}<b>${capacity(l.branch)}</b></div><button class="icon-btn" type="button" data-action="remove-line" data-index="${i}" ${d.lines.length===1?'disabled':''} aria-label="${t('حذف الموقع','Remove location')}">${icon('trash')}</button></div>`).join('')}<div style="margin-top:14px">${btn(icon('plus')+t('إضافة موقع','Add location'),'add-line','small','type="button" '+(d.lines.length>=3?'disabled':''))}</div></div><div class="spacer"></div><div class="note blue">${t('الأعداد في هذا النموذج توضيحية. لا تُحدّث سجلات قنديل أو الهيكل الفعلي.','These quantities are illustrative. They do not update Kandil’s real records or organization.')}</div>`;}
function stepTwo(d){return `<h2>${t('التفاصيل تصنع قرارًا أفضل','Give your reviewer the right context')}</h2><p class="form-intro">${t('وضح سبب الاحتياج وموعد الانضمام المناسب.','Explain why the role is needed and when the person should start.')}</p><div class="form-grid">${field('priority',t('الأولوية','Priority'),`<select id="priority" name="priority"><option value="normal" ${d.priority==='normal'?'selected':''}>${t('عادي','Normal')}</option><option value="urgent" ${d.priority==='urgent'?'selected':''}>${t('عاجل','Urgent')}</option></select>`)}${field('start',t('تاريخ الانضمام المستهدف *','Target joining date *'),`<input type="date" id="start" name="start" value="${esc(d.start)}">`)}<div class="full">${field('reason',t('سبب الاحتياج *','Hiring justification *'),`<textarea id="reason" name="reason" maxlength="2000" placeholder="${t('مثلًا: زيادة حجم العمل أو تعويض وظيفة شاغرة...','For example: increased workload or replacing an open role…')}">${esc(d.reason)}</textarea>`,t('10 أحرف على الأقل. لا تدخل بيانات شخصية حقيقية.','At least 10 characters. Do not enter real personal data.'))}</div>${field('type',t('نوع التوظيف','Employment type'),`<select id="type" name="type"><option value="full" ${d.type==='full'?'selected':''}>${t('دوام كامل','Full time')}</option><option value="fixed" ${d.type==='fixed'?'selected':''}>${t('عقد محدد المدة','Fixed-term contract')}</option></select>`)}</div>`;}
function summary(r){return `<dl class="summary-list"><div><dt>${t('الوظيفة','Role')}</dt><dd>${jobLabel(r.job)}</dd></div><div><dt>${t('الإدارة','Department')}</dt><dd>${depLabel(r.department)}</dd></div><div><dt>${t('إجمالي الاحتياج','Total headcount')}</dt><dd>${total(r)} ${t('موظفين','positions')}</dd></div><div><dt>${t('الانضمام المستهدف','Target joining date')}</dt><dd><bdi>${esc(r.start||'—')}</bdi></dd></div><div><dt>${t('نوع التوظيف','Employment type')}</dt><dd>${r.type==='fixed'?t('عقد محدد المدة','Fixed-term contract'):t('دوام كامل','Full time')}</dd></div><div><dt>${t('الأولوية','Priority')}</dt><dd>${r.priority==='urgent'?t('عاجل','Urgent'):t('عادي','Normal')}</dd></div></dl><div class="note"><strong>${t('سبب الاحتياج','Hiring justification')}</strong><p>${esc(state.lang==='en'&&r.reasonEn?r.reasonEn:r.reason)}</p></div><div class="spacer"></div><div class="table-wrap"><table style="min-width:280px"><thead><tr><th>${t('الموقع','Location')}</th><th>${t('العدد المطلوب','Requested')}</th></tr></thead><tbody>${r.lines.map(l=>`<tr><td>${branchLabel(l.branch)}</td><td>${esc(l.qty)}</td></tr>`).join('')}</tbody></table></div>`;}
function stepThree(d){return `<h2>${t('جاهز للإرسال؟','Ready to submit?')}</h2><p class="form-intro">${t('راجع البيانات. سيظهر الطلب في قائمة مراجعة الموارد البشرية.','Review the details. This request will appear in the HR approval inbox.')}</p>${summary(d)}<div class="spacer"></div><div class="note blue">${t('المراجع التالي: مريم أحمد · مديرة الموارد البشرية.','Next reviewer: Mariam Ahmed · HR manager.')}</div>`;}
function render(){document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr';document.title=t('قنديل | بوابة الموارد البشرية','Kandil | People portal');$('#app').innerHTML=state.role?shell(({dashboard,requests,approvals,vacancies,new:wizard}[route]||dashboard)()):login();}
function openModal(title,body,foot='',wide=false){modalFocus=document.activeElement;$('#overlay-root').innerHTML=`<div class="overlay" data-action="backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="modal-head"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="${t('إغلاق','Close')}">${icon('close')}</button></header><div class="modal-body">${body}</div>${foot?`<footer class="modal-footer">${foot}</footer>`:''}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('.modal input:not([type=hidden]),.modal textarea,.modal button')?.focus(),0);}
function closeModal(){const wasOpen=!!$('.modal');$('#overlay-root').innerHTML='';document.body.style.overflow='';if(wasOpen&&modalFocus?.isConnected)modalFocus.focus();}
function detail(id){const r=state.requests.find(x=>x.id===id);if(!r)return;const canReview=state.role==='hr'&&r.status==='pending';const events={submitted:['أُرسل للاعتماد','Submitted for approval'],approved:['اعتمد الطلب وفتح الشواغر','Approved and vacancies created'],returned:['أُعيد للتعديل','Returned for changes']};openModal(`${jobLabel(r.job)} <span class="badge draft ltr">${r.id}</span>`,`${badge(r.status)}<div class="spacer"></div>${summary(r)}${r.note?`<div class="spacer"></div><div class="note red"><strong>${t('ملاحظة المراجع','Reviewer note')}</strong><p>${esc(r.note)}</p></div>`:''}<section class="timeline"><h3>${t('سجل الطلب','Request timeline')}</h3>${r.history.map(e=>`<div class="timeline-row">${icon('check')}<div><strong>${t(...events[e.action])}</strong><small>${person(e.actor)} · ${when(e.date)}</small></div></div>`).join('')}</section>${canReview?`<div class="note blue">${t('تراجع الإصدار','Reviewing revision')} ${r.revision}. ${t('عند الاعتماد سيُفتح شاغر مستقل لكل موقع.','Approval creates a separate vacancy for each location.')}</div>`:''}`,canReview?btn(t('إعادة للتعديل','Request changes'),'return-start','',`data-id="${r.id}"`)+btn(icon('check')+t('اعتماد وفتح الشواغر','Approve & create vacancies'),'approve-start','green',`data-id="${r.id}"`):r.status==='returned'&&r.owner===state.role?btn(t('تعديل وإعادة إرسال','Edit & resubmit'),'revise','primary',`data-id="${r.id}"`):btn(t('إغلاق','Close'),'close'),true);}
function vacancyDetail(id){const v=state.vacancies.find(x=>x.id===id);if(!v)return;openModal(jobLabel(v.job),`${badge(v.status)}<div class="spacer"></div><dl class="summary-list"><div><dt>${t('الموقع','Location')}</dt><dd>${branchLabel(v.branch)}</dd></div><div><dt>${t('الطلب المصدر','Source request')}</dt><dd class="ltr">${v.request}</dd></div><div><dt>${t('العدد المعتمد','Approved headcount')}</dt><dd>${v.qty}</dd></div><div><dt>${t('المتبقي','Remaining')}</dt><dd>${v.qty-v.filled}</dd></div></dl>${field('lead',t('مسؤول التوظيف','Lead recruiter'),`<select id="lead" ${state.role!=='hr'?'disabled':''}><option value="">${t('لم يُعيّن بعد','Unassigned')}</option><option value="salma" ${v.lead==='salma'?'selected':''}>${t('سلمى محمد','Salma Mohamed')}</option><option value="ahmed" ${v.lead==='ahmed'?'selected':''}>${t('أحمد سامي','Ahmed Samy')}</option></select>`)}<div class="spacer"></div><div class="note">${t('إدارة المرشحين والمقابلات ستُضاف بعد اعتماد تجربة الطلب والاعتماد والشواغر.','Candidate and interview workflows follow after this request–approval–vacancy experience is approved.')}</div>`,state.role==='hr'?btn(v.status==='open'?t('إيقاف مؤقت','Pause hiring'):t('استئناف التوظيف','Resume hiring'),'toggle-vacancy','',`data-id="${v.id}"`)+btn(t('حفظ المسؤول','Save recruiter'),'save-lead','primary',`data-id="${v.id}"`):btn(t('إغلاق','Close'),'close'));}
function capture(){if(route!=='new'||!state.draft)return;for(const k of ['department','job','priority','reason','start','type']){const el=$('#'+k);if(el)state.draft[k]=el.value;}document.querySelectorAll('[data-line][data-field]').forEach(el=>{const l=state.draft.lines[Number(el.dataset.line)];if(l)l[el.dataset.field]=el.dataset.field==='qty'?Number(el.value):el.value;});}
function validate(stage){const d=state.draft;if(stage===1){if(d.lines.some(l=>!Number.isInteger(l.qty)||l.qty<1))return t('أدخل عددًا صحيحًا لا يقل عن 1 لكل موقع.','Enter a whole number of at least 1 for each location.');if(new Set(d.lines.map(l=>l.branch)).size!==d.lines.length)return t('اختر كل موقع مرة واحدة فقط.','Each location can appear only once.');if(d.lines.some(l=>l.qty>capacity(l.branch)))return t('العدد يتجاوز المتاح في هذا النموذج. عدّل العدد للمتابعة؛ مسار استثناء العدد خارج هذه التجربة.','The quantity exceeds this demo’s available capacity. Reduce it to continue; exception approval is outside this prototype.');}if(stage===2){if(d.reason.trim().length<10)return t('وضح سبب الاحتياج في 10 أحرف على الأقل.','Provide at least 10 characters of hiring justification.');if(!d.start)return t('اختر تاريخ الانضمام المستهدف.','Choose a target joining date.');}return '';}
async function submit(){capture();const error=validate(1)||validate(2);if(error){$('#form-error').textContent=error;return;}if(busy)return;busy=true;$('#wizard-next').disabled=true;await new Promise(r=>setTimeout(r,350));const d=state.draft;let r=state.requests.find(x=>x.id===d.id);if(r&&r.status!=='returned'){busy=false;toast(t('تم إرسال هذا الطلب بالفعل.','This request has already been submitted.'));go('requests');return;}if(r){r={...r,...structuredClone(d),owner:'manager',status:'pending',revision:r.revision+1,reasonEn:undefined,note:null};state.requests=state.requests.map(x=>x.id===r.id?r:x);}else{r={...structuredClone(d),id:'HR-2026-'+String(state.next++).padStart(3,'0'),owner:'manager',status:'pending',revision:1,history:[],seed:false};state.requests.push(r);}r.history.push({action:'submitted',actor:'manager',date:new Date().toISOString()});state.draft=null;save();busy=false;go('requests');openModal(t('تم إرسال الطلب','Request submitted'),`<div class="success-panel"><div class="success-icon">${icon('check')}</div><h2>${t('خطوة أقرب لفريق مكتمل.','One step closer to a complete team.')}</h2><p><bdi>${r.id}</bdi><br>${t('الطلب الآن بانتظار مراجعة مريم أحمد. بدّل الدور لتجربة قرار الاعتماد.','Your request is waiting for Mariam Ahmed. Switch roles to experience the approval decision.')}</p><div class="actions">${btn(t('تجربة دور المراجع','Continue as HR reviewer'),'review-submitted','primary',`data-id="${r.id}"`)}${btn(t('البقاء في طلباتي','Stay in my requests'),'close')}</div></div>`);}
function decide(id,kind){const r=state.requests.find(x=>x.id===id);if(state.role!=='hr'||r?.status!=='pending')return;let note='';if(kind==='returned'){note=$('#return-note')?.value.trim()||'';if(note.length<5){$('#return-error').textContent=t('اكتب ملاحظة واضحة من 5 أحرف على الأقل.','Add a clear note of at least 5 characters.');return;}}r.status=kind;r.note=note||null;r.history.push({action:kind,actor:'hr',date:new Date().toISOString()});if(kind==='approved'){for(const [i,l] of r.lines.entries()){const id=`${r.id}-V${i+1}`;if(!state.vacancies.some(v=>v.id===id))state.vacancies.push({id,request:r.id,job:r.job,department:r.department,branch:l.branch,qty:l.qty,filled:0,status:'open',priority:r.priority,lead:''});}}save();closeModal();render();if(kind==='approved'){openModal(t('تم الاعتماد','Request approved'),`<div class="success-panel"><div class="success-icon">${icon('check')}</div><h2>${t('الشواغر جاهزة لفريق التوظيف.','Ready for your recruiting team.')}</h2><p>${t('تم فتح','Created')} ${r.lines.length} ${t('شاغر بعدد إجمالي','vacancies with a total of')} ${total(r)} ${t('موظفين. يمكنك الآن تعيين مسؤول التوظيف.','positions. You can now assign a lead recruiter.')}</p>${btn(t('عرض الشواغر','View vacancies'),'goto','primary','data-page="vacancies"')}</div>`);}else toast(t('أُعيد الطلب مع ملاحظتك.','Request returned with your note.'));}
function guide(){openModal(t('جرّب الرحلة كاملة','Try the complete journey'),[['1',t('اختر عمر حسن لإنشاء طلب، أو ابدأ من طلب تجريبي موجود.','Choose Omar Hassan to create a request, or open a seeded request.')],['2',t('حدد الوظيفة والمواقع والأعداد، ثم أكمل التفاصيل وأرسل الطلب.','Choose a role, locations and quantities. Add the details and submit.')],['3',t('بدّل إلى مريم أحمد من أعلى الصفحة. راجع الطلب ثم اعتمد أو أعده بملاحظة.','Switch to Mariam Ahmed above. Review, approve or request changes.')],['4',t('افتح الشواغر لتجد شاغرًا لكل موقع. عيّن مسؤول التوظيف وجرّب الإيقاف والاستئناف.','Open Vacancies to see one record per location. Assign a recruiter and try pause/resume.')]].map(([n,text])=>`<div class="tour-step"><b>${n}</b><p>${text}</p></div>`).join('')+`<div class="spacer"></div><div class="note">${t('اختيار الدور محاكاة للتصميم وليس تسجيل دخول آمنًا. كل البيانات في متصفحك فقط، ولا يوجد اتصال بـ Frappe.','Role selection simulates the design; it is not secure authentication. All data stays in this browser. There is no Frappe connection.')}</div>`,btn(icon('reset')+t('إعادة بيانات التجربة','Reset demo data'),'reset-start')+btn(t('ابدأ طلبًا','Start a request'),'new','primary'));}
function openSearch(){openModal(t('ابحث في مساحة عملك','Search your workspace'),`<div class="search-field" style="max-width:none">${icon('search')}<input id="global-search" placeholder="${t('وظيفة، موقع، أو رقم طلب...','Role, location or request ID…')}" aria-label="${t('بحث شامل','Global search')}"></div><div id="global-results" class="search-results"></div>`);setTimeout(()=>$('#global-search')?.focus(),0);updateSearch('');}
function updateSearch(q){const req=ownRequests().filter(r=>matches(r,q)).slice(0,5);const vac=state.vacancies.filter(v=>matches(v,q)).slice(0,4);$('#global-results').innerHTML=req.map(r=>`<button class="search-result" data-action="detail" data-id="${r.id}">${icon('file')}<span>${jobLabel(r.job)}<small>${r.id} · ${t('طلب توظيف','Hiring request')}</small></span></button>`).join('')+vac.map(v=>`<button class="search-result" data-action="vacancy" data-id="${v.id}">${icon('briefcase')}<span>${jobLabel(v.job)}<small>${branchLabel(v.branch)} · ${t('شاغر','Vacancy')}</small></span></button>`).join('')||empty(t('لا توجد نتائج','No results'),t('جرّب اسم وظيفة أو رقم طلب آخر.','Try another role or request ID.'));}
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-route]');if(nav){e.preventDefault();capture();save();go(nav.dataset.route);return;}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(a==='backdrop'&&e.target!==b)return;e.preventDefault();switch(a){
case 'login':state.role=loginRole;save();go('dashboard');break;
case 'language':capture();state.lang=state.lang==='ar'?'en':'ar';save();closeModal();render();break;
case 'menu':mobileOpen=!mobileOpen;render();break;
case 'new':go('new');break;
case 'goto':go(b.dataset.page);break;
case 'guide':guide();break;
case 'close':case 'backdrop':closeModal();break;
case 'detail':detail(id);break;
case 'vacancy':vacancyDetail(id);break;
case 'home-tab':homeTab=b.dataset.tab;render();break;
case 'filter':filter=b.dataset.filter;render();break;
case 'search':openSearch();break;
case 'profile':openModal(person(state.role),`<p>${roleLabel(state.role)}</p><div class="spacer"></div><div class="note">${t('حساب تجريبي. يمكنك تبديل الدور من أعلى الصفحة.','Demo account. You can switch roles at the top of the page.')}</div>`,btn(icon('reset')+t('إعادة التجربة','Reset demo'),'reset-start')+btn(icon('logout')+t('خروج','Sign out'),'logout'));break;
case 'logout':state.role=null;save();closeModal();render();break;
case 'notifications':openModal(t('الإشعارات','Notifications'),taskRows(ownRequests().filter(r=>['pending','returned'].includes(r.status)).slice(0,4)));break;
case 'next':capture();{const error=validate(step);if(error){$('#form-error').textContent=error;break;}step++;save();render();window.scrollTo(0,0);}break;
case 'previous':capture();step--;save();render();break;
case 'save-draft':capture();save();toast(t('حُفظت المسودة في هذا المتصفح.','Draft saved in this browser.'));break;
case 'add-line':capture();{const branch=Object.keys(branches).find(k=>!state.draft.lines.some(l=>l.branch===k));if(branch)state.draft.lines.push({branch,qty:1});save();render();}break;
case 'remove-line':capture();if(state.draft.lines.length>1)state.draft.lines.splice(Number(b.dataset.index),1);save();render();break;
case 'submit-request':await submit();break;
case 'switch-manager':state.role='manager';save();render();break;
case 'review-submitted':state.role='hr';save();go('approvals');detail(id);break;
case 'approve-start':{const r=state.requests.find(r=>r.id===id);if(state.role!=='hr'||r?.status!=='pending')break;openModal(t('تأكيد الاعتماد','Confirm approval'),`<p>${t('سيُعتمد طلب','Approve')} <strong>${jobLabel(r.job)}</strong> ${t('بعدد','for')} <strong>${total(r)}</strong> ${t('موظفين، وسيُفتح شاغر لكل موقع.','positions and create one vacancy per location.')}</p><div class="spacer"></div><div class="note">${t('قرار تجريبي فقط — لا يُرسل إشعارات حقيقية ولا يعدّل Frappe.','Demo decision only — no real notifications or Frappe changes.')}</div>`,btn(t('رجوع','Back'),'detail','',`data-id="${id}"`)+btn(t('تأكيد وفتح الشواغر','Confirm & create vacancies'),'approve-confirm','green',`data-id="${id}"`));}break;
case 'approve-confirm':decide(id,'approved');break;
case 'return-start':openModal(t('إعادة الطلب للتعديل','Request changes'),field('return-note',t('ملاحظتك لصاحب الطلب *','Your note to the requester *'),`<textarea id="return-note" maxlength="1000" placeholder="${t('وضح ما يحتاج إلى تعديل...','Explain what needs to change…')}"></textarea>`)+`<div id="return-error" class="field-error" role="alert"></div>`,btn(t('رجوع','Back'),'detail','',`data-id="${id}"`)+btn(t('إرسال الملاحظة','Send feedback'),'return-confirm','primary',`data-id="${id}"`));break;
case 'return-confirm':decide(id,'returned');break;
case 'revise':{const r=state.requests.find(r=>r.id===id);if(r?.owner===state.role&&r.status==='returned'){state.draft=structuredClone(r);save();go('new');}}break;
case 'save-lead':{const v=state.vacancies.find(v=>v.id===id);if(v&&state.role==='hr'){v.lead=$('#lead').value;save();closeModal();render();toast(t('تم حفظ مسؤول التوظيف.','Lead recruiter saved.'));}}break;
case 'toggle-vacancy':{const v=state.vacancies.find(v=>v.id===id);if(v&&state.role==='hr'){v.status=v.status==='open'?'paused':'open';save();closeModal();render();toast(t('تم تحديث حالة الشاغر.','Vacancy status updated.'));}}break;
case 'reset-start':openModal(t('إعادة بيانات التجربة؟','Reset the demo?'),`<p>${t('ستُحذف الطلبات التجريبية التي أضفتها هنا وتعود البيانات النموذجية. لا يؤثر ذلك على أي نظام آخر.','This removes requests you created in this prototype and restores the sample data. No other system is affected.')}</p>`,btn(t('إلغاء','Cancel'),'close')+btn(t('إعادة التجربة','Reset demo'),'reset-confirm','primary'));break;
case 'reset-confirm':{const lang=state.lang,role=state.role;state=initial();state.lang=lang;state.role=role;save();go('dashboard');toast(t('بدأت تجربة جديدة.','Demo reset.'));}break;
}});
document.addEventListener('change',e=>{const el=e.target;if(el.name==='loginRole'){loginRole=el.value;render();}if(el.id==='demo-role'){capture();state.role=el.value;save();closeModal();render();toast(t('تم تبديل الدور التجريبي.','Demo role switched.'));}if(route==='new'&&(el.name||el.dataset.line!==undefined)){capture();if(el.id==='department')state.draft.job=Object.keys(jobs).find(k=>jobs[k][2]===state.draft.department);save();if(el.id==='department'||el.dataset.field==='branch')render();}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='list-search'){const start=el.selectionStart;search=el.value;render();$('#list-search')?.focus();$('#list-search')?.setSelectionRange(start,start);}if(el.id==='global-search')updateSearch(el.value);if(route==='new'&&(el.name||el.dataset.line!==undefined)){capture();save();}});
document.addEventListener('submit',e=>{if(e.target.id==='request-form')e.preventDefault();});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'&&state.role){e.preventDefault();openSearch();}if(e.key==='Escape'){closeModal();if(mobileOpen){mobileOpen=false;render();}}if(e.key==='Tab'&&$('.modal')){const all=[...$('.modal').querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]')];const first=all[0],last=all.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(labels[next]&&next!==route){capture();route=next;filter='all';search='';closeModal();if(next==='new')ensureDraft();render();}});
if(labels[location.hash.slice(1)])route=location.hash.slice(1);
render();
})();
